extends CharacterBody2D


# Player movement speed
const SPEED = 100.0
var velocity := Vector2.ZERO

@onready var sprite = $Sprite2D
@onready var hud = $"../Hud"
@onready var input_router = $"../InputRouter"

func _physics_process(delta):
	velocity.x = 0
	if input_router.ui_left:
		velocity.x -= SPEED
	if input_router.ui_right:
		velocity.x += SPEED

	move_and_slide()

	hud.update_player_position(position)

	if input_router.ui_accept:
		jump()

extends CharacterBody2D


# Player movement speed
const SPEED = 100.0
var velocity := Vector2.ZERO

@onready var sprite = $Sprite2D
@onready var hud = $"../Hud"
@onready var input_router = $"../InputRouter"

func take_hit(v):
	damage += v
	if damage > 0:
		sprite.modulate.a = 0.5
	else:
		sprite.modulate.a = 1.0

func _physics_process(delta):
	velocity.x = 0
	if input_router.ui_left:
		velocity.x -= SPEED
	if input_router.ui_right:
		velocity.x += SPEED

	move_and_slide()

	hud.update_player_position(position)

	if input_router.ui_accept:
		jump()


func _enter_tree():
	connect("body_entered", func(body):
		if body.is_in_group("Player"):
			take_hit(1)
			queue_free())

